def _host_length_values(lengths, batch_size):
    """仅对能在主机侧无损读取的长度序列返回 Python 列表，否则返回 None。"""
    if isinstance(lengths, (list, tuple)):
        values = [int(value) for value in lengths]
    elif torch.is_tensor(lengths) and lengths.device.type == "cpu":
        values = [int(value) for value in lengths.reshape(-1).tolist()]
    else:
        return None
    if len(values) != batch_size:
        return None
    return values


def _build_length_tensors(host_input, host_target, device, batch_size, pack):
    """构造 kernel 所需的三段 int64 长度数据；pack=1 时合并为一次 H2D。"""
    running_total = 0
    host_offsets = []
    for target_length in host_target:
        host_offsets.append(running_total)
        running_total += target_length
    if pack:
        merged_values = list(host_input) + list(host_target) + host_offsets
        merged = torch.tensor(merged_values, dtype=torch.long, device=device)
        return (
            merged[:batch_size],
            merged[batch_size : 2 * batch_size],
            merged[2 * batch_size :],
        )
    return (
        torch.tensor(host_input, dtype=torch.long, device=device),
        torch.tensor(host_target, dtype=torch.long, device=device),
        torch.tensor(host_offsets, dtype=torch.long, device=device),
    )


def _length_statistics(host_values):
    """返回 (min, max, sum)，语义与原 _length_stats 的三个 reduction 一致。"""
    return min(host_values), max(host_values), sum(host_values)


